package mz.bam.seeky.voicebridge;
import android.app.*;import android.content.*;import android.os.*;import android.speech.tts.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Real two-process Android test, deterministic PCM producer; no neural performance claim. */
public final class BridgeProof extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();NaturalSpeech client=null;try{Context c=getTargetContext();CountDownLatch init=new CountDownLatch(1);AtomicReference<NaturalSpeech> ref=new AtomicReference<>();AtomicInteger status=new AtomicInteger(99);new Handler(Looper.getMainLooper()).post(()->ref.set(new NaturalSpeech(c,code->{status.set(code);init.countDown();},new ComponentName(c,Producer.class))));if(!init.await(20,TimeUnit.SECONDS)||status.get()!=0)throw new IOException("Direct connection failed "+status.get());client=ref.get();if(client.getVoices().size()!=1)throw new IOException("Missing direct catalogue");Voice v=client.getVoices().iterator().next();if(client.setVoice(v)!=0)throw new IOException("Voice rejected");result.putBoolean("direct_catalogue",true);sendStatus(1,result);
  CountDownLatch saved=new CountDownLatch(1);AtomicInteger errors=new AtomicInteger(),ranges=new AtomicInteger(),starts=new AtomicInteger();NaturalSpeech owner=client;
  client.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){starts.incrementAndGet();}public void onDone(String id){saved.countDown();}public void onError(String id){errors.incrementAndGet();saved.countDown();}public void onError(String id,int code){onError(id);}public void onRangeStart(String id,int start,int end,int frame){ranges.incrementAndGet();}});
  File out=new File(c.getFilesDir(),"proof.wav");if(client.synthesizeToFile("Primeira frase. Segunda frase.",null,out,"save")!=0||!saved.await(20,TimeUnit.SECONDS)||errors.get()!=0)throw new IOException("WAV generation failed");try(RandomAccessFile f=new RandomAccessFile(out,"r")){byte[] head=new byte[44];f.readFully(head);if(!new String(head,0,4,"US-ASCII").equals("RIFF")||f.length()!=8864)throw new IOException("Invalid WAV "+f.length());}result.putBoolean("two_process_pcm_to_wav",true);result.putLong("wav_bytes",out.length());sendStatus(2,result);
  CountDownLatch played=new CountDownLatch(1);client.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){starts.incrementAndGet();}public void onDone(String id){played.countDown();}public void onError(String id){errors.incrementAndGet();played.countDown();}public void onError(String id,int code){onError(id);}public void onRangeStart(String id,int start,int end,int frame){ranges.incrementAndGet();}});
  if(client.speak("Primeira frase. Segunda frase.",TextToSpeech.QUEUE_FLUSH,null,"play")!=0||!played.await(20,TimeUnit.SECONDS)||errors.get()!=0)throw new IOException("Streaming playback failed: "+client.getFailureReason()+" active="+(client.active==null?"none":client.active.stage+" frames="+client.active.frames+" cancelled="+client.active.cancelled+" gen="+client.active.generation+"/"+client.generation.get()+" result="+client.active.result.getCount())+" pending="+client.pending.get()+" starts="+starts.get()+" errors="+errors.get());result.putBoolean("streamed_audio_track",true);result.putInt("ranges",ranges.get());result.putInt("starts",starts.get());if(ranges.get()<1)throw new IOException("No spoken range");
  client.shutdown();client=null;CountDownLatch moduleReady=new CountDownLatch(1);AtomicReference<NaturalSpeech> module=new AtomicReference<>();AtomicInteger moduleCode=new AtomicInteger(99);new Handler(Looper.getMainLooper()).post(()->module.set(new NaturalSpeech(c,code->{moduleCode.set(code);moduleReady.countDown();})));if(!moduleReady.await(20,TimeUnit.SECONDS)||moduleCode.get()!=0)throw new IOException("Production module bridge failed "+moduleCode.get());client=module.get();result.putInt("production_catalogue",client.getVoices().size());int installed=0;for(Voice actual:client.getVoices())if(!actual.getFeatures().contains(TextToSpeech.Engine.KEY_FEATURE_NOT_INSTALLED))installed++;result.putInt("preserved_installed_voices",installed);if(client.getVoices().size()!=7||installed<1)throw new IOException("Production catalogue/model was lost");client.shutdown();client=null;result.putBoolean("success",true);
 }catch(Throwable e){result.putBoolean("success",false);result.putString("exception",android.util.Log.getStackTraceString(e));}finally{if(client!=null)client.shutdown();finish(Activity.RESULT_OK,result);}}
 public static final class Producer extends Service {
  final Set<ParcelFileDescriptor> outputs=Collections.synchronizedSet(new HashSet<>());
  public IBinder onBind(Intent i){return new Messenger(new Handler(Looper.getMainLooper(),message->{Messenger target=message.replyTo;if(message.what==NaturalSpeech.HELLO){Bundle b=new Bundle();ArrayList<Voice> voices=new ArrayList<>();voices.add(new Voice("Direct test",new Locale("pt","PT"),400,200,false,new HashSet<>(Arrays.asList("seeky:piper-v1","seeky:rate=22050"))));b.putParcelableArrayList("voices",voices);send(target,NaturalSpeech.CATALOG,b);}else if(message.what==NaturalSpeech.SYNTH){Bundle b=message.getData();ParcelFileDescriptor output=b.getParcelable("output");String key=b.getString("key");outputs.add(output);new Thread(()->{try(DataOutputStream out=new DataOutputStream(new ParcelFileDescriptor.AutoCloseOutputStream(output))){Bundle mark=new Bundle();mark.putString("key",key);mark.putInt("frame",0);mark.putInt("start",0);mark.putInt("end",8);send(target,NaturalSpeech.RANGE,mark);byte[] pcm=new byte[8820];for(int n=0;n<4410;n++){int value=(int)(Math.sin(n*.12)*5000);pcm[n*2]=(byte)value;pcm[n*2+1]=(byte)(value>>8);}for(int offset=0;offset<pcm.length;offset+=4096){int length=Math.min(4096,pcm.length-offset);out.writeInt(length);out.write(pcm,offset,length);}out.writeInt(0);}catch(IOException ignored){}finally{outputs.remove(output);Bundle done=new Bundle();done.putString("key",key);send(target,NaturalSpeech.DONE,done);}},"proof-pcm").start();}else if(message.what==NaturalSpeech.CANCEL||message.what==NaturalSpeech.BYE){synchronized(outputs){for(ParcelFileDescriptor fd:outputs)try{fd.close();}catch(IOException ignored){}outputs.clear();}}return true;})).getBinder();}
  static void send(Messenger target,int code,Bundle data){try{Message reply=Message.obtain(null,code);reply.setData(data);target.send(reply);}catch(RemoteException ignored){}}
 }
}
